-- MIGRATION 1: base
CREATE TABLE `roles` (`id` BIGINT NOT NULL AUTO_INCREMENT, `name` VARCHAR(80) NOT NULL UNIQUE, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `users` (`id` BIGINT NOT NULL AUTO_INCREMENT, `role_id` BIGINT NOT NULL, `email` VARCHAR(255) NOT NULL UNIQUE, PRIMARY KEY (`id`), CONSTRAINT `fk_users_role` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE `orders` (`id` BIGINT NOT NULL AUTO_INCREMENT, `user_id` BIGINT NOT NULL, `total` DECIMAL(12,2) NOT NULL DEFAULT 0, PRIMARY KEY (`id`), CONSTRAINT `fk_orders_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE INDEX `idx_users_role` ON `users` (`role_id`);
CREATE VIEW `active_users` AS SELECT `id`,`email` FROM `users`;
DELIMITER $$
CREATE PROCEDURE `noop_proc`() BEGIN SELECT 1; END$$
CREATE TRIGGER `trg_users_touch` BEFORE UPDATE ON `users` FOR EACH ROW SET @x=1$$
DELIMITER ;
